values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'sprouts' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Parent questions","title":"Everything you need to know","items":[{"question":"What ages do you accept?","answer":"We welcome children from 2 to 10 years old, from Toddlers through to Primary."},{"question":"What are the school hours?","answer":"School runs from 8:30 AM to 2:00 PM. After-school care is available until 5:30 PM."},{"question":"Do you provide meals?","answer":"Yes. Our kitchen prepares fresh, healthy snacks and lunch every day, with options for allergies."},{"question":"How do I apply?","answer":"Book a visit, meet our teachers and fill in a short form. We will confirm your child''s place within a week."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'sprouts';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'sprouts' and c.slug in ('school', 'coaching-institute', 'online-education');
